    "renfo.prog.home.label": "Home (bands + dumbbells)", "renfo.prog.home.intro": "With a little gear at home: resistance bands and/or dumbbells (or a loaded backpack, water bottles).",
    "renfo.prog.gym.label": "Gym", "renfo.prog.gym.intro": "At the gym, with barbells, machines and load: maximum strength for the runner (heavy moves, few reps).",
    "renfo.none.b1.group": "Core / trunk", "renfo.none.b1.intro": "A solid core = stable pelvis and less energy lost on every stride.",
    "renfo.none.b1.e1.name": "Plank", "renfo.none.b1.e1.dose": "3 × 45 s", "renfo.none.b1.e1.cue": "Body aligned heels-hips-shoulders, abs and glutes tight, don't let your back sag.",
    "renfo.none.b1.e2.name": "Side plank", "renfo.none.b1.e2.dose": "3 × 30 s / side", "renfo.none.b1.e2.cue": "On the forearm, hips high. Strengthens obliques and glute medius (pelvic stability).",
    "renfo.none.b1.e3.name": "Dead bug", "renfo.none.b1.e3.dose": "3 × 10 / side", "renfo.none.b1.e3.cue": "On your back, lower opposite arm + leg without lifting your lower back off the floor.",
    "renfo.none.b1.e4.name": "Mountain climbers", "renfo.none.b1.e4.dose": "3 × 30 s", "renfo.none.b1.e4.cue": "In a plank, drive the knees in alternately, core braced, controlled rhythm.",
    "renfo.none.b2.group": "Posterior chain & glutes", "renfo.none.b2.intro": "The runner's engine: glutes and hamstrings protect the knees and propel you.",
    "renfo.none.b2.e1.name": "Glute bridge", "renfo.none.b2.e1.dose": "3 × 15", "renfo.none.b2.e1.cue": "Lift the hips squeezing the glutes hard at the top, feet flat.",
    "renfo.none.b2.e2.name": "Single-leg glute bridge", "renfo.none.b2.e2.dose": "3 × 10 / leg", "renfo.none.b2.e2.cue": "One leg straight, lift the hips with the other. Harder, anti-imbalance.",
    "renfo.none.b2.e3.name": "Forward lunges", "renfo.none.b2.e3.dose": "3 × 10 / leg", "renfo.none.b2.e3.cue": "Big step, back knee toward the floor, torso upright, front knee behind the toes.",
    "renfo.none.b2.e4.name": "Bodyweight squats", "renfo.none.b2.e4.dose": "3 × 15", "renfo.none.b2.e4.cue": "Sit the hips back, flat back, thighs to horizontal, weight on the heels.",
    "renfo.none.b3.group": "Calves & feet", "renfo.none.b3.intro": "The runner's #1 injury zone (Achilles, shin splints). An absolute must to strengthen.",
    "renfo.none.b3.e1.name": "Calf raises", "renfo.none.b3.e1.dose": "3 × 15", "renfo.none.b3.e1.cue": "On a step, rise onto the toes slowly, drop below horizontal. Also with bent knee (soleus).",
    "renfo.none.b3.e2.name": "Eccentric Achilles", "renfo.none.b3.e2.dose": "3 × 12", "renfo.none.b3.e2.cue": "Rise on 2 feet, lower slowly on just 1. Tendon prevention +++.",
    "renfo.none.b4.group": "Balance & explosiveness", "renfo.none.b4.intro": "Stability, foot responsiveness, sprain prevention (especially on trails).",
    "renfo.none.b4.e1.name": "Single-leg balance", "renfo.none.b4.e1.dose": "3 × 30 s / foot", "renfo.none.b4.e1.cue": "On one foot, knee soft. Progression: eyes closed, then on a cushion.",
    "renfo.none.b4.e2.name": "Squat jump", "renfo.none.b4.e2.dose": "3 × 10", "renfo.none.b4.e2.cue": "Squat then explosive jump, soft landing on the forefoot. Elastic stiffness.",
    "renfo.home.b1.group": "Core / trunk", "renfo.home.b1.intro": "We add resistance and anti-rotation.",
    "renfo.home.b1.e1.name": "Pallof press (band)", "renfo.home.b1.e1.dose": "3 × 12 / side", "renfo.home.b1.e1.cue": "Band to the side, extend the arms forward resisting rotation. Anti-rotation = key to useful core work.",
    "renfo.home.b1.e2.name": "Weighted plank", "renfo.home.b1.e2.dose": "3 × 40 s", "renfo.home.b1.e2.cue": "Plank with a dumbbell or a bag on the upper back. Stay perfectly braced.",
    "renfo.home.b1.e3.name": "Russian twist (dumbbell)", "renfo.home.b1.e3.dose": "3 × 16", "renfo.home.b1.e3.cue": "Seated, torso leaned back, rotate the trunk with a weight. Obliques.",
    "renfo.home.b2.group": "Posterior chain & glutes", "renfo.home.b2.intro": "The added resistance maximises the strength gain.",
    "renfo.home.b2.e1.name": "Goblet squat (dumbbell)", "renfo.home.b2.e1.dose": "3 × 12", "renfo.home.b2.e1.cue": "A dumbbell/kettlebell held against the chest, deep squat, straight back.",
    "renfo.home.b2.e2.name": "Romanian deadlift (dumbbells)", "renfo.home.b2.e2.dose": "3 × 10", "renfo.home.b2.e2.cue": "Flat back, lower the dumbbells along the legs pushing the hips back. Stretches the hamstrings.",
    "renfo.home.b2.e3.name": "Dumbbell lunges", "renfo.home.b2.e3.dose": "3 × 10 / leg", "renfo.home.b2.e3.cue": "A dumbbell in each hand, controlled lunge.",
    "renfo.home.b2.e4.name": "Hip abduction (band)", "renfo.home.b2.e4.dose": "3 × 15 / side", "renfo.home.b2.e4.cue": "Band at the ankles/knees, drive the leg out. Targets the glute medius (pelvic stability).",
    "renfo.home.b2.e5.name": "Weighted glute bridge", "renfo.home.b2.e5.dose": "3 × 12", "renfo.home.b2.e5.cue": "Glute bridge with a dumbbell on the hips or a band above the knees.",
    "renfo.home.b3.group": "Calves & posture", "renfo.home.b3.intro": "Light load to keep progressing.",
    "renfo.home.b3.e1.name": "Calf raises with dumbbells", "renfo.home.b3.e1.dose": "3 × 15", "renfo.home.b3.e1.cue": "A dumbbell in each hand, raises on a step.",
    "renfo.home.b3.e2.name": "Band row (back/posture)", "renfo.home.b3.e2.dose": "3 × 15", "renfo.home.b3.e2.cue": "Band anchored in front, pull squeezing the shoulder blades. Improves running posture.",
    "renfo.home.b4.group": "Balance & explosiveness",
    "renfo.home.b4.e1.name": "Jump lunge", "renfo.home.b4.e1.dose": "3 × 8 / leg", "renfo.home.b4.e1.cue": "Lunge then jump, switching legs in the air. Power + balance.",
    "renfo.home.b4.e2.name": "Balance + dumbbell", "renfo.home.b4.e2.dose": "3 × 30 s / foot", "renfo.home.b4.e2.cue": "On one foot, move a dumbbell around you to destabilise.",
    "renfo.gym.b1.group": "Lower-body strength (heavy)", "renfo.gym.b1.intro": "Max strength improves running economy. Heavy loads, perfect technique.",
    "renfo.gym.b1.e1.name": "Barbell squat", "renfo.gym.b1.e1.dose": "4 × 6-8", "renfo.gym.b1.e1.cue": "Bar on the traps, descend thighs parallel, braced back. Progressive load.",
    "renfo.gym.b1.e2.name": "Barbell hip thrust", "renfo.gym.b1.e2.dose": "4 × 8", "renfo.gym.b1.e2.cue": "Back on a bench, bar on the hips (pad), drive squeezing the glutes at the top.",
    "renfo.gym.b1.e3.name": "Bulgarian split squat (dumbbells)", "renfo.gym.b1.e3.dose": "3 × 8 / leg", "renfo.gym.b1.e3.cue": "Back foot raised on a bench, descend vertically. Unilateral = anti-imbalance.",
    "renfo.gym.b1.e4.name": "Leg press", "renfo.gym.b1.e4.dose": "3 × 10", "renfo.gym.b1.e4.cue": "Full range, don't lift the hips, control the descent.",
    "renfo.gym.b2.group": "Hamstrings & posterior chain", "renfo.gym.b2.intro": "Often neglected, essential against injuries.",
    "renfo.gym.b2.e1.name": "Romanian deadlift (barbell)", "renfo.gym.b2.e1.dose": "3 × 8", "renfo.gym.b2.e1.cue": "Flat back, bar close to the legs, hips back. Controlled hamstring stretch.",
    "renfo.gym.b2.e2.name": "Leg curl (machine)", "renfo.gym.b2.e2.dose": "3 × 12", "renfo.gym.b2.e2.cue": "Isolates the hamstrings, slow and full movement.",
    "renfo.gym.b3.group": "Calves",
    "renfo.gym.b3.e1.name": "Calf extension (machine)", "renfo.gym.b3.e1.dose": "4 × 12", "renfo.gym.b3.e1.cue": "Max range, pause at the top, slow descent.",
    "renfo.gym.b3.e2.name": "Seated calf raise (soleus)", "renfo.gym.b3.e2.dose": "3 × 15", "renfo.gym.b3.e2.cue": "Seated machine, bent knee: targets the soleus (key for running).",
    "renfo.gym.b4.group": "Core & explosiveness",
    "renfo.gym.b4.e1.name": "Pallof press (cable)", "renfo.gym.b4.e1.dose": "3 × 12 / side", "renfo.gym.b4.e1.cue": "Cable to the side, anti-rotation with arms extended.",
    "renfo.gym.b4.e2.name": "Box jumps", "renfo.gym.b4.e2.dose": "3 × 6", "renfo.gym.b4.e2.cue": "Explosive jump onto a box, soft landing. Power + stiffness.",
    "renfo.gym.b4.e3.name": "Bosu balance", "renfo.gym.b4.e3.dose": "3 × 30 s", "renfo.gym.b4.e3.cue": "Standing on a Bosu, stabilise. Advanced proprioception.",
