    "renfo.none.b1.e4.name": "Mountain climbers", "renfo.none.b1.e4.dose": "3 × 30 s", "renfo.none.b1.e4.cue": "En plancha, lleva las rodillas alternando, core firme, ritmo controlado.",
    "renfo.none.b2.group": "Cadena posterior y glúteos", "renfo.none.b2.intro": "El motor del corredor: glúteos e isquiotibiales protegen las rodillas y propulsan.",
    "renfo.none.b2.e1.name": "Puente de glúteos", "renfo.none.b2.e1.dose": "3 × 15", "renfo.none.b2.e1.cue": "Sube la pelvis apretando fuerte los glúteos arriba, pies planos.",
    "renfo.none.b2.e2.name": "Puente de glúteos a una pierna", "renfo.none.b2.e2.dose": "3 × 10 / pierna", "renfo.none.b2.e2.cue": "Una pierna estirada, sube la pelvis con la otra. Más difícil, antidesequilibrio.",
    "renfo.none.b2.e3.name": "Zancadas hacia delante", "renfo.none.b2.e3.dose": "3 × 10 / pierna", "renfo.none.b2.e3.cue": "Paso grande, rodilla trasera hacia el suelo, tronco recto, rodilla delantera detrás de la punta.",
    "renfo.none.b2.e4.name": "Sentadillas con peso corporal", "renfo.none.b2.e4.dose": "3 × 15", "renfo.none.b2.e4.cue": "Lleva las nalgas atrás, espalda plana, muslos a la horizontal, peso en los talones.",
    "renfo.none.b3.group": "Gemelos y pies", "renfo.none.b3.intro": "Zona de lesión nº 1 del corredor (Aquiles, periostitis). Imprescindible reforzarla.",
    "renfo.none.b3.e1.name": "Elevaciones de gemelos", "renfo.none.b3.e1.dose": "3 × 15", "renfo.none.b3.e1.cue": "En un escalón, sube de puntillas despacio, baja por debajo de la horizontal. También con la rodilla flexionada (sóleo).",
